metadata.orrery:spec:
# yaml-language-server: $schema=https://raw.githubusercontent.com/Sagargupta16/orrery/main/skills/orrery/references/diagram.schema.json
# Source: docs/diagrams/issue-to-live.plan.md (confirmed by the owner, 19 November 2026).
# Framing k1: a flowchart whose eight stages are boxes on a serpentine, read at 880 CSS px.
title: From issue to live change
subtitle: How one request moves through the intentable loop
kind: flowchart
direction: down
skin: classic
# packets is SMIL only (no CSS, no script), which GitHub keeps in an SVG shown as an image.
# The numbered steps run one after another, so one marker travels from open to close.
animate: packets
layout: { spacing: 0.5 }

# The path the marker walks when the stage skin is used instead.
story:
  - open
  - questions
  - answers
  - proposal
  - reviewers
  - draft
  - page
  - feedback
  - pick
  - approve-step
  - build-step
  - pr
  - preview-data
  - preview-site
  - preview-link
  - merge
  - deploy
  - close

# Who acts at each step. People's steps are warm colors (and slanted boxes, the
# ISO 5807 manual operation); automatic steps are cool colors.
tags:
  requester: { color: "#d97706", label: "Requester: a person (slanted box)" }
  owner: { color: "#db2777", label: "Owner: a person (slanted box)" }
  agent: { color: "#7c3aed", label: "Agent: Claude Code in a Daytona sandbox" }
  bridge: { color: "#2563eb", label: "Bridge: intentable, automatic" }
  service: { color: "#0d9488", label: "Service: hosting automation" }

classes:
  step: { shape: process }

# The eight stages, in order. They outline their steps after layout (around:), so the
# rows below can fold the path into a serpentine three steps wide.
groups:
  ask: { type: zone, label: Ask, around: [open] }
  clarify: { type: zone, label: Clarify, around: [questions, answers] }
  propose: { type: zone, label: Propose, around: [proposal, reviewers, draft, page] }
  shape: { type: zone, label: Shape, around: [feedback, pick] }
  approve: { type: zone, label: Approve, around: [approve-step] }
  build: { type: zone, label: Build, around: [build-step, pr] }
  preview: { type: zone, label: Preview, around: [preview-data, preview-site, preview-link] }
  ship: { type: zone, label: Ship, around: [merge, deploy, close] }

# Nodes are listed row by row, left to right as drawn (align: puts a step beside the
# one it names). The flow order is the edges' step numbers and the story above.
nodes:
  # Row 1, left to right: Ask, Clarify
  open:
    { shape: terminator, icon: tabler:user, label: Opens an issue, note: "Requester, on GitHub", tags: [requester] }
  questions:
    { align: open, class: step, icon: logos:claude-code, label: Asks questions, note: "One at a time; issue: needs-info", tags: [agent] }
  answers:
    { align: open, shape: manual, icon: tabler:user, label: Answers on the issue, note: Each reply starts the agent again, tags: [requester] }
  # Rows 2 and 3: Propose, down the right side and then right to left
  proposal:
    { class: step, icon: logos:claude-code, label: Writes a proposal, note: "OpenSpec, plus sketches of new screens", tags: [agent] }
  page:
    { align: reviewers, class: step, icon: si:github, label: Publishes proposal page, note: "Spek on GitHub Pages, with the sketches", tags: [service] }
  draft:
    { align: reviewers, class: step, icon: tabler:git-branch, label: Commits the draft, note: Branch change/<name>, tags: [bridge] }
  reviewers:
    { class: step, icon: logos:claude-code, label: Reviews the proposal, note: "Three reviewers: risk, spec fit, fidelity; up to five rounds", badge: x3, tags: [agent] }
  # Row 4, left to right: Shape, Approve
  feedback:
    { shape: manual, icon: tabler:user, label: Gives feedback, note: "Anyone on the intake list; the agent revises", tags: [requester] }
  pick:
    { align: feedback, shape: manual, icon: tabler:user, label: Picks a sketch, note: Replies with its letter, tags: [requester] }
  approve-step:
    { align: feedback, shape: manual, icon: tabler:user-check, label: Comments /approve, note: "Owner's gate G2, recorded on the draft branch", tags: [owner] }
  # Row 5, right to left: Build
  pr:
    { align: build-step, class: step, icon: tabler:git-pull-request, label: Opens pull request, note: "issue: awaiting-merge", tags: [bridge] }
  build-step:
    { class: step, icon: logos:claude-code, label: Builds and tests, note: The full test suite must pass, tags: [agent] }
  # Rows 6 and 7: Preview, right to left and then down
  preview-site:
    { align: preview-data, class: step, icon: gcp:cloud-run, label: Deploys a preview, note: "Google Cloud Run, one per pull request", tags: [service] }
  preview-data:
    { class: step, icon: logos:neon-icon, label: Branches the data, note: Neon branch of last night's cleaned live data, tags: [service] }
  preview-link:
    { class: step, icon: tabler:plug-connected, label: Posts preview link, note: "issue: preview-ready", tags: [bridge] }
  # Row 8, left to right: Ship
  merge:
    { shape: manual, icon: tabler:user-check, label: Merges pull request, note: "Owner, after checking the preview; issue: merged", tags: [owner] }
  deploy:
    { align: merge, class: step, icon: si:render, label: Deploys the site, note: Render deploys main once its tests pass, tags: [service] }
  close:
    { align: merge, shape: terminator, icon: tabler:circle-check, label: Closes the issue, note: "Change is live; issue: deployed", tags: [bridge] }

# One path, numbered in order.
edges:
  - open -> questions: { label: starts the agent, step: 1 }
  - questions -> answers: { label: question on the issue, step: 2 }
  - answers -> proposal: { label: clear enough, step: 3 }
  - proposal -> reviewers: { label: to review, step: 4 }
  - reviewers -> draft: { label: reviewed draft, step: 5 }
  - draft -> page: { label: push builds the page, step: 6 }
  - page -> feedback: { label: page link on the issue, step: 7 }
  - feedback -> pick: { label: agent revises them, step: 8 }
  - pick -> approve-step: { label: pick recorded, step: 9 }
  - approve-step -> build-step: { label: starts the build, step: 10 }
  - build-step -> pr: { label: tested commits, step: 11 }
  - pr -> preview-data: { label: starts the preview, step: 12 }
  - preview-data -> preview-site: { label: data for the preview, step: 13 }
  - preview-site -> preview-link: { label: preview is up, step: 14 }
  - preview-link -> merge: { label: owner checks it, step: 15 }
  - merge -> deploy: { label: tests pass on main, step: 16 }
  - deploy -> close: { label: deploy reported, step: 17 }
